# mobile
def mlot(k,lot,status,pl,pv,tl,tv,ex=''):
    t,a,d=IMG[k][1],IMG[k][2],IMG[k][3]
    return f'''<div class="card" style="overflow:hidden;display:flex">{img(k,'','132').replace('width:100%','') .replace('class="art ','style="width:112px;min-height:132px;align-self:stretch;flex:none" class="art ')}<div style="padding:10px 12px;flex:1;min-width:0" class="col"><div class="row" style="justify-content:space-between">{status}<span class="xs muted">Lote {lot}</span></div><b class="serif" style="font-size:15px;margin-top:6px;line-height:1.2">{t}</b><span class="xs muted">{a} · {d}</span><div class="sp"></div><div class="kv"><span class="xs">{pl}</span><span class="price">{pv}</span></div><div class="kv"><span class="xs">{tl}</span><span class="num small" style="font-weight:600">{tv}</span></div>{ex}</div></div>'''
def mframe(lbl,inner,h=844):
    return f'<div><div class="flabel"><b>{lbl[0]}</b>{lbl[1]}</div><div class="frame" style="width:390px;height:{h}px;border-radius:24px">{inner}</div></div>'
ml=''.join([mlot('socr','0007',L,'Atual','R$ 12.400,00','Termina','02:14:09'),mlot('wave','0003',L,'Atual','R$ 4.200,00','Termina','00:01:42'),mlot('wheat','0011',L,'Inicial','R$ 20.000,00','Termina','1 d 04 h'),mlot('charp','0009',L,'Atual','R$ 8.750,00','Termina','05:40:22')])
